<?php

declare(strict_types=1);

use Phit\Polyfill\Internal\Bobyqa;
use Phit\Polyfill\Internal\Bobyqa\BobyqaException;
use Phit\Polyfill\Internal\Bobyqa\Config;
use Phit\Polyfill\Internal\Bobyqa\Linalg;
use Phit\Polyfill\Internal\Bobyqa\RestartConfig;
use Phit\Polyfill\Internal\Bobyqa\Status;
use Phit\Polyfill\Internal\Jit;

/*
 * tests/fixtures/bobyqa-reference.json is generated by the Rust harness in
 * tests/reference/bobyqa against the bobyqa crate 0.3.2. Floats are IEEE-754 bit
 * patterns in hex; trace_crc is the CRC-32 of every point the solver evaluated.
 */

require_once __DIR__.'/../Support/bobyqa.php';

dataset('bobyqa reference', function () {
    foreach (loadFixture('bobyqa-reference.json') as $row) {
        yield $row['name'] => [$row];
    }
});

/*
 * The reference is checked in two tests, because a JIT can miscompile the
 * solver's arithmetic (php-src #24214) and send the search down another path.
 * Which status the solver reports, how it labels it, and whether it found a
 * finite point survive that and are checked everywhere. The evaluation count,
 * the objective, the solution, the restart count and the CRC of every
 * evaluated point do not survive it, and are checked where the arithmetic can
 * be trusted. PHP 8.4.26 on GitHub's x86-64 runner moved one case's objective
 * by 18%; see docs/notes/function-jit.md.
 */

it('agrees with the crate on the status and the finiteness', function (array $row) {
    [$outcome] = bobyqaRun($row);

    expect($outcome->status->name)->toBe($row['status'])
        ->and($outcome->status->label())->toBe($row['display'])
        ->and($outcome->foundFinite())->toBe($row['found_finite']);
})->with('bobyqa reference');

it('reproduces the crate bit for bit', function (array $row) {
    if (Jit::compiling()) {
        test()->markTestSkipped('the exact reproduction needs a process without a JIT (php-src #24214)');
    }
    [$outcome, $x, $trace, $solver] = bobyqaRun($row);

    expect($outcome->nEval)->toBe($row['n_eval'])
        ->and(bobyqaHex($outcome->f))->toBe($row['f'])
        ->and(array_map(bobyqaHex(...), $x))->toBe($row['x'])
        ->and($solver->lastRestartCount())->toBe($row['restarts'])
        ->and(crc32($trace))->toBe($row['trace_crc']);
})->with('bobyqa reference');

it('covers the statuses the extension distinguishes', function () {
    $statuses = array_column(loadFixture('bobyqa-reference.json'), 'status');

    expect($statuses)->toContain('Converged', 'MaxFunReached', 'TargetReached', 'FtolReached');
});

it('starts from the crate defaults', function () {
    $config = new Config(3);
    $restart = new RestartConfig;

    expect($config->npt)->toBe(7)
        ->and($config->rhoBegin)->toBe(1.0)
        ->and($config->rhoEnd)->toBe(1.0e-6)
        ->and($config->maxFun)->toBe(1500)
        ->and($config->fTarget)->toBe(-INF)
        ->and($config->restart)->toBeNull()
        ->and($config->ftolRel)->toBeNull()
        ->and($config->ftolAbs)->toBeNull()
        ->and($config->primaParity)->toBeTrue()
        ->and([$restart->maxRestarts, $restart->improveRelTol, $restart->stallReductions, $restart->cycleBudgetFrac])
        ->toBe([1, 1e-6, 0, 0.125]);
});

it('rejects invalid configurations with the crate message', function (int $n, Closure $edit) {
    $config = new Config(max($n, 1));
    $edit($config);
    try {
        new Bobyqa($n, $config);
        $this->fail('expected a BobyqaException');
    } catch (BobyqaException $e) {
        expect($e->status)->toBe(Status::InvalidArgs)
            ->and($e->getMessage())->toBe('invalid arguments: bad bounds, npt, sizes, or config');
    }
})->with([
    'n = 0' => [0, fn (Config $c) => null],
    'npt below n + 2' => [2, fn (Config $c) => $c->npt = 3],
    'npt above (n + 1)(n + 2) / 2' => [2, fn (Config $c) => $c->npt = 7],
    'rho_end zero' => [2, fn (Config $c) => $c->rhoEnd = 0.0],
    'rho_end above rho_begin' => [2, fn (Config $c) => $c->rhoEnd = 2.0],
    'rho_begin infinite' => [2, function (Config $c) {
        $c->rhoBegin = INF;
        $c->rhoEnd = 1.0;
    }],
    'rho_begin NaN' => [2, fn (Config $c) => $c->rhoBegin = NAN],
    'max_fun not above npt' => [2, fn (Config $c) => $c->maxFun = 5],
    'f_target NaN' => [2, fn (Config $c) => $c->fTarget = NAN],
    'f_target +inf' => [2, fn (Config $c) => $c->fTarget = INF],
    'ftol negative' => [2, fn (Config $c) => $c->ftolAbs = -1.0],
    'ftol NaN' => [2, fn (Config $c) => $c->ftolRel = NAN],
    'cycle budget NaN' => [2, function (Config $c) {
        $c->restart = new RestartConfig;
        $c->restart->cycleBudgetFrac = NAN;
    }],
    'no restarts' => [2, function (Config $c) {
        $c->restart = new RestartConfig;
        $c->restart->maxRestarts = 0;
    }],
]);

it('returns an InvalidArgs outcome for bad runtime arguments', function (array $x, array $lower, array $upper) {
    $solver = new Bobyqa(2, new Config(2));
    $calls = 0;
    $outcome = $solver->minimize(function (array $p) use (&$calls): float {
        $calls++;

        return $p[0];
    }, $x, $lower, $upper);

    expect($outcome->status)->toBe(Status::InvalidArgs)
        ->and($outcome->nEval)->toBe(0)
        ->and(is_nan($outcome->f))->toBeTrue()
        ->and($outcome->foundFinite())->toBeFalse()
        ->and($calls)->toBe(0);
})->with([
    'x length' => [[0.0], [-1.0, -1.0], [1.0, 1.0]],
    'NaN bound' => [[0.0, 0.0], [NAN, -1.0], [1.0, 1.0]],
    'crossed bounds' => [[0.0, 0.0], [2.0, -1.0], [1.0, 1.0]],
    'box narrower than 2 rho_begin' => [[0.0, 0.0], [-0.5, -1.0], [0.5, 1.0]],
    'NaN x' => [[NAN, 0.0], [-9.0, -9.0], [9.0, 9.0]],
    'bound collapses after the BOUNDMAX clamp' => [[0.0, 0.0], [-INF, -9.0], [-1e308, 9.0]],
]);

it('labels every status with the crate Display text', function () {
    expect(array_map(fn (Status $s) => $s->label(), Status::cases()))->toBe([
        'the trust-region radius reached rho_end, with any restart schedule settled',
        'an evaluation reached f_target',
        'the best f improved by less than the ftol tolerance over one rho stage',
        'the max_fun evaluation budget was exhausted',
        'the interpolation model degenerated beyond rescue',
        'invalid arguments: bad bounds, npt, sizes, or config',
        'the solver workspace could not be allocated',
    ]);
});

it('mirrors Rust f64::max and f64::min', function () {
    expect(Linalg::max(NAN, 1.0))->toBe(1.0)
        ->and(Linalg::max(1.0, NAN))->toBe(1.0)
        ->and(Linalg::min(NAN, -1.0))->toBe(-1.0)
        ->and(bobyqaHex(Linalg::max(-0.0, 0.0)))->toBe('0000000000000000')
        ->and(bobyqaHex(Linalg::max(0.0, -0.0)))->toBe('0000000000000000')
        ->and(bobyqaHex(Linalg::min(0.0, -0.0)))->toBe('8000000000000000')
        ->and(bobyqaHex(Linalg::min(-0.0, 0.0)))->toBe('8000000000000000')
        ->and(Linalg::midpoint(PHP_FLOAT_MAX, PHP_FLOAT_MAX))->toBe(PHP_FLOAT_MAX);
});
